import type {
  AIToolbarProps,
  AIToolbarTriggerProps,
  AIToolbarTriggerLeadingProps,
  AIToolbarTriggerTrailingProps,
  AIToolbarContentProps,
  AIToolbarTextProps,
} from "./ai-toolbar.types";

import {
  Children,
  cloneElement,
  forwardRef,
  isValidElement,
  useId,
  useState,
  useEffect,
  useRef,
  useCallback,
  useMemo,
} from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { usePortalContainer } from "@hooks/use-portal-container";
import { Button } from "@components/button";
import { IconButton } from "@components/icon-button";

import { AIToolbarClasses, StyledAIToolbar } from "./ai-toolbar.styles";
import { AIToolbarContext, useAIToolbar } from "./hooks/use-ai-toolbar";

const isInteractiveElement = (child: React.ReactNode): boolean => {
  if (!isValidElement(child)) return false;

  const type = child.type;
  if (type === Button || type === IconButton) return true;

  if (typeof type === "string") {
    if (["button", "a", "input", "select", "textarea"].includes(type)) return true;
  }

  const props = child.props;
  if (props && (props.onClick || props.href)) return true;

  return false;
};

const AIToolbar = forwardRef<HTMLDivElement, AIToolbarProps>(
  (
    {
      children,
      className,
      defaultExpanded = false,
      expanded: expandedProp,
      onExpandChange,
      thinking = false,
      containerElement,
      variant = "default",
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const [internalExpanded, setInternalExpanded] = useState(defaultExpanded);
    const { resolvedContainer, isScoped } = usePortalContainer(containerElement);
    const contentId = useId();

    const [hasContent, setHasContent] = useState(false);
    const registerContent = useCallback(() => setHasContent(true), []);
    const unregisterContent = useCallback(() => setHasContent(false), []);

    const isControlled = expandedProp !== undefined;
    const expanded = isControlled ? expandedProp : internalExpanded;

    const setExpanded = (newExpanded: boolean) => {
      if (!isControlled) {
        setInternalExpanded(newExpanded);
      }
      onExpandChange?.(newExpanded);
    };

    const rootClasses = clsx(AIToolbarClasses.root, className);

    return (
      <AIToolbarContext.Provider
        value={{
          expanded,
          setExpanded,
          thinking,
          resolvedContainer,
          isScoped,
          contentId,
          hasContent,
          registerContent,
          unregisterContent,
        }}
      >
        <StyledAIToolbar
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          data-state={expanded ? "expanded" : "collapsed"}
          data-textura-scoped={isScoped}
          data-thinking={thinking}
          variant={variant}
          {...props}
        >
          {children}
        </StyledAIToolbar>
      </AIToolbarContext.Provider>
    );
  },
);
AIToolbar.displayName = "AIToolbar";

const TriggerLeading = forwardRef<HTMLDivElement, AIToolbarTriggerLeadingProps>(
  ({ children, className, ...props }, ref) => (
    <div ref={ref} className={clsx(AIToolbarClasses.triggerLeading, className)} {...props}>
      {children}
    </div>
  ),
);
TriggerLeading.displayName = "AIToolbar.TriggerLeading";

const TriggerTrailing = forwardRef<HTMLDivElement, AIToolbarTriggerTrailingProps>(
  ({ children, className, ...props }, ref) => (
    <div ref={ref} className={clsx(AIToolbarClasses.triggerTrailing, className)} {...props}>
      {Children.map(children, (child) => {
        if (isValidElement(child) && child.type === Button) {
          return cloneElement(child, {
            buttonType: child.props.buttonType ?? "tertiary",
            variant: child.props.variant ?? "desaturated",
          });
        }
        return child;
      })}
    </div>
  ),
);
TriggerTrailing.displayName = "AIToolbar.TriggerTrailing";

const Text = forwardRef<HTMLSpanElement, AIToolbarTextProps>(
  ({ children, className, variant = "default", ...props }, ref) => (
    <span
      ref={ref}
      className={clsx(AIToolbarClasses.text, className)}
      data-variant={variant}
      {...props}
    >
      {Children.map(children, (child) => {
        if (isValidElement(child)) {
          return child;
        }
        if (typeof child === "string" || typeof child === "number") {
          return <span className={AIToolbarClasses.textContent}>{child}</span>;
        }
        return child;
      })}
    </span>
  ),
);
Text.displayName = "AIToolbar.Text";

const hasInteractiveChildren = (children: React.ReactNode): boolean => {
  let found = false;
  Children.forEach(children, (child) => {
    if (found) return;
    if (isInteractiveElement(child)) {
      found = true;
      return;
    }
    if (isValidElement(child) && child.type === TriggerTrailing) {
      Children.forEach(child.props.children, (trailingChild) => {
        if (found) return;
        if (isInteractiveElement(trailingChild)) found = true;
      });
    }
  });
  return found;
};

const Trigger = forwardRef<HTMLDivElement, AIToolbarTriggerProps>(
  ({ children, className, thinking: thinkingProp, onClick, onKeyDown, ...props }, ref) => {
    const { setExpanded, expanded, thinking: ctxThinking, contentId, hasContent } = useAIToolbar();
    const isThinking = thinkingProp ?? ctxThinking;
    const shouldSplit = useMemo(() => hasInteractiveChildren(children), [children]);

    const handleExpand = () => !expanded && setExpanded(true);

    const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
      handleExpand();
      onClick?.(e);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (!expanded && (e.key === "Enter" || e.key === " ")) {
        e.preventDefault();
        handleExpand();
      }
      onKeyDown?.(e);
    };

    const commonProps = {
      ref,
      className: clsx(AIToolbarClasses.trigger, className),
      "data-thinking": isThinking,
      onClick: handleClick,
      ...props,
    };

    const ariaProps = hasContent ? { "aria-controls": contentId, "aria-expanded": expanded } : {};

    if (shouldSplit) {
      return (
        <div aria-expanded={ariaProps["aria-expanded"]} role="group" {...commonProps}>
          {Children.map(children, (child) =>
            isValidElement(child) && child.type === TriggerLeading
              ? cloneElement(child, {
                  role: "button",
                  tabIndex: expanded ? -1 : 0,
                  onKeyDown: handleKeyDown,
                  ...ariaProps,
                } as React.HTMLAttributes<HTMLDivElement>)
              : child,
          )}
        </div>
      );
    }

    return (
      <div
        role="button"
        tabIndex={expanded ? -1 : 0}
        onKeyDown={handleKeyDown}
        {...ariaProps}
        {...commonProps}
      >
        {children}
      </div>
    );
  },
);
Trigger.displayName = "AIToolbar.Trigger";

const Content = forwardRef<HTMLDivElement, AIToolbarContentProps>(
  ({ children, className, ...props }, ref) => {
    const { contentId, expanded, registerContent, unregisterContent } = useAIToolbar();
    const contentRef = useRef<HTMLDivElement | null>(null);

    const handleRef = (node: HTMLDivElement | null) => {
      contentRef.current = node;
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    };

    useEffect(() => {
      registerContent();
      return () => {
        unregisterContent();
      };
    }, [registerContent, unregisterContent]);

    useEffect(() => {
      if (contentRef.current) {
        if (!expanded) {
          contentRef.current.setAttribute("inert", "true");
        } else {
          contentRef.current.removeAttribute("inert");
        }
      }
    }, [expanded]);

    // Auto-focus logic
    useEffect(() => {
      if (expanded && contentRef.current) {
        requestAnimationFrame(() => {
          if (!contentRef.current) return;

          // Priority 1: Inputs and Textareas (for immediate typing)
          let target = contentRef.current.querySelector<HTMLElement>(
            'input:not([type="hidden"]), textarea',
          );

          // Priority 2: Any other focusable element
          if (!target) {
            target = contentRef.current.querySelector<HTMLElement>(
              'button, [href], select, [tabindex]:not([tabindex="-1"])',
            );
          }

          target?.focus();
        });
      }
    }, [expanded]);

    return (
      <div
        ref={handleRef}
        className={clsx(AIToolbarClasses.content, className)}
        id={contentId}
        {...props}
      >
        {children}
      </div>
    );
  },
);
Content.displayName = "AIToolbar.Content";

type AIToolbarCompoundComponent = typeof AIToolbar & {
  Trigger: typeof Trigger;
  TriggerLeading: typeof TriggerLeading;
  TriggerTrailing: typeof TriggerTrailing;
  Text: typeof Text;
  Content: typeof Content;
};

const AIToolbarCompound = AIToolbar as AIToolbarCompoundComponent;

AIToolbarCompound.Trigger = Trigger;
AIToolbarCompound.TriggerLeading = TriggerLeading;
AIToolbarCompound.TriggerTrailing = TriggerTrailing;
AIToolbarCompound.Text = Text;
AIToolbarCompound.Content = Content;

export default AIToolbarCompound;
